      Scene_TileSelectionResult.originalResult(lastFrameSelectionResult) ===
      Scene_TileSelectionResult.RENDERED;
    const twoCulledOrNotVisited =
      Scene_TileSelectionResult.originalResult(lastFrameSelectionResult) ===
        Scene_TileSelectionResult.CULLED ||
      lastFrameSelectionResult === Scene_TileSelectionResult.NONE;
