    `RECEIVING: ${loadStateByCount[Scene_KeyframeNode.LoadState.RECEIVING]} | ` +
    `PROCESSING: ${loadStateByCount[Scene_KeyframeNode.LoadState.PROCESSING]} | ` +
    `LOADED: ${loadStateByCount[Scene_KeyframeNode.LoadState.LOADED]} | ` +
    `FAILED: ${loadStateByCount[Scene_KeyframeNode.LoadState.FAILED]} | ` +
    `UNAVAILABLE: ${loadStateByCount[Scene_KeyframeNode.LoadState.UNAVAILABLE]} | ` +
    `TOTAL: ${nodeCountTotal}`;

